actions.script:
// Delete ALL existing authz for this role+module combo (seed data + custom)
def existingList = ec.entity.find("moqui.security.ArtifactAuthz")
    .condition("userGroupId", userGroupId)
    .condition("artifactGroupId", artifactGroupId)
    .list()
for (def existing : existingList) { existing.delete() }

String authzId = "ZC_${userGroupId}_${artifactGroupId}".toString()
if (accessLevel == "VIEW") {
    ec.entity.makeValue("moqui.security.ArtifactAuthz").setAll([
        artifactAuthzId: authzId, userGroupId: userGroupId,
        artifactGroupId: artifactGroupId,
        authzTypeEnumId: "AUTHZT_ALLOW", authzActionEnumId: "AUTHZA_VIEW"
    ]).createOrUpdate()
} else if (accessLevel == "FULL") {
    ec.entity.makeValue("moqui.security.ArtifactAuthz").setAll([
        artifactAuthzId: authzId, userGroupId: userGroupId,
        artifactGroupId: artifactGroupId,
        authzTypeEnumId: "AUTHZT_ALLOW", authzActionEnumId: "AUTHZA_ALL"
    ]).createOrUpdate()
}

if (userId == ec.user.userId) return
def myT = ec.entity.find("moqui.security.UserGroupMember").condition("userId", ec.user.userId).list()*.userGroupId.findAll{ it?.startsWith('TENANT_') }
def authorized = false
if (myT) {
    def theirs = ec.entity.find("moqui.security.UserGroupMember").condition("userId", userId).list()*.userGroupId
    authorized = theirs.any { myT.contains(it) }
}
if (!authorized) ec.message.addError('Not authorized to manage a user outside your organization')
